# The oracle is deliberately the original CPU PDM implementation.  It is
# exact, but a training batch contains independent T4 samples; keeping one
# serial Python loop per DDP rank leaves most of the Slurm CPU allocation idle.
# A per-rank process pool parallelizes only those independent samples.  It does
# not change proposal generation, simulator/scorer code, floating-point
# operations, or result ordering.
_T4_ORACLE_EXECUTOR: ProcessPoolExecutor | None = None
_T4_ORACLE_EXECUTOR_WORKERS = 0


def _t4_oracle_worker_init() -> None:
    """Keep each exact oracle worker single-threaded and CPU-local."""

    # The worker imports torch through this module, but must never initialize a
    # CUDA context or create an internal CPU thread pool.  BLAS pools are also
    # pinned to one thread: with up to 128 oracle workers per node, letting
    # each spawn an OpenMP team oversubscribes the box.  numpy's elementwise
    # kernels and scipy's Hungarian solver are single-threaded exact
    # algorithms, so this changes scheduling only, never a value.
    for name in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS"):
        os.environ.setdefault(name, "1")
    torch.set_num_threads(1)
    try:
        torch.set_num_interop_threads(1)
    except RuntimeError:
        # PyTorch permits setting this only before its first parallel region.
        # It is a performance hint and has no effect on oracle values.
        pass


def _t4_oracle_worker_count(task_count: int) -> int:
    """Choose exact per-rank CPU parallelism without changing the algorithm."""

    configured = os.environ.get("T4E2E_ORACLE_WORKERS")
    if configured is not None and configured.strip():
        try:
            workers = int(configured)
        except ValueError as exc:
            raise ValueError(
                "T4E2E_ORACLE_WORKERS must be a positive integer"
            ) from exc
    else:
        # The launcher reserves eight CPUs per DDP rank and two DataLoader
        # workers.  Leave the main process and those workers one CPU slot;
        # fall back to serial execution outside Slurm.
        try:
            cpus_per_task = int(os.environ.get("SLURM_CPUS_PER_TASK", "1"))
        except ValueError:
            cpus_per_task = 1
        workers = max(1, cpus_per_task - 3)
    return max(1, min(int(task_count), workers))


# Mapping one window per worker caps the pool at the batch size, so a large
# CPU allocation stays idle.  Splitting a window's proposals across workers
# lifts that cap and is numerically identical - every PDM metric is computed
# per proposal, and the EP normalisation compares each proposal against the
# scalar pdm_progress - so the split is available here.  It is off by default
# because it does not pay on this workload:
#
#   scripts/profile_t4_oracle.py: one window is ~417 ms, of which ~132 ms is
#   per-window setup independent of the proposal count (the 51-frame PDM
#   observation alone is 122 ms) and ~285 ms scales with it.  Each chunk
#   repeats the setup, so the compute-side ceiling is 1.5x at 2 chunks and
#   2.0x at 4.
#
#   scripts/bench_t4_oracle_chunks.py (real pool, four batches, three
#   interleaved rounds): 129.5 -> 124.8 -> 125.2 ms per sample for 1, 2 and 4
#   chunks, i.e. 1.03x for four times the process count.  Batch wall time is
#   set by the slowest window, and 32 concurrent map/observation builds per
#   rank contend for memory bandwidth, which cancels the projected gain.
#
# UPDATE after the lean observation build: the economics flipped.  The
# per-window setup that every chunk used to repeat fell from ~132 ms to a few
# tens of ms, and the same interleaved benchmark now measures 446.8 -> 299.0
# -> 276.6 ms per batch for 1/2/4 chunks (1.49x / 1.61x), bit-identical.  On
# the eight-rank launch, chunks=2 means 8 x 16 = 128 oracle workers plus 64
# loader workers on 224 cores -- fits; chunks=4 would oversubscribe.  The
# recommended launch setting is T4E2E_ORACLE_PROPOSAL_CHUNKS=2.
_MIN_PROPOSALS_PER_CHUNK = 16


def _t4_oracle_chunk_count(batch_size: int, proposal_count: int, workers: int) -> int:
    """Split each window's proposals only as far as it stays worthwhile."""

    configured = os.environ.get("T4E2E_ORACLE_PROPOSAL_CHUNKS")
    if configured is None or not configured.strip():
        return 1
    try:
        chunks = int(configured)
    except ValueError as exc:
        raise ValueError(
            "T4E2E_ORACLE_PROPOSAL_CHUNKS must be a positive integer"
        ) from exc
    if chunks < 1:
        raise ValueError("T4E2E_ORACLE_PROPOSAL_CHUNKS must be >= 1")
    return max(1, min(chunks, max(1, int(proposal_count) // _MIN_PROPOSALS_PER_CHUNK)))


def _get_t4_oracle_executor(workers: int) -> ProcessPoolExecutor | None:
    """Return one persistent exact worker pool per training process."""

    global _T4_ORACLE_EXECUTOR, _T4_ORACLE_EXECUTOR_WORKERS
    if workers <= 1:
        return None
    if _T4_ORACLE_EXECUTOR is None or _T4_ORACLE_EXECUTOR_WORKERS != workers:
        if _T4_ORACLE_EXECUTOR is not None:
            _T4_ORACLE_EXECUTOR.shutdown(wait=True, cancel_futures=True)
        _T4_ORACLE_EXECUTOR = ProcessPoolExecutor(
            max_workers=workers,
            mp_context=mp.get_context("spawn"),
            initializer=_t4_oracle_worker_init,
        )
        _T4_ORACLE_EXECUTOR_WORKERS = workers
    return _T4_ORACLE_EXECUTOR


