def aggregate_t4_pdms(
    components: torch.Tensor,
    score_weights: Sequence[float] = DEFAULT_T4_PDMS_WEIGHTS,
) -> torch.Tensor:
    """Apply the original six-head PDMS aggregation to probabilities.

    Formal T4 labels use ``PDMScorer.score_proposals`` directly.  This helper
    remains for inference/tests and mirrors the paper's post-hoc six-head
    weighted aggregate without adding any hidden metric.
    """

    if components.shape[-1] < 6:
        raise ValueError(
            "T4 PDMS aggregation requires six components, "
            f"got {tuple(components.shape)}"
        )
    weights = tuple(float(value) for value in score_weights)
    if (
        len(weights) != 6
        or not np.isfinite(weights).all()
        or any(value < 0.0 for value in weights)
    ):
        raise ValueError("T4 PDMS score_weights must contain six finite non-negative values")
    denominator = sum(weights[2:])
    if denominator <= 0.0:
        raise ValueError("T4 PDMS behavior weights must sum to > 0")
    weight_tensor = torch.as_tensor(
        weights, device=components.device, dtype=components.dtype
    )
    values = components[..., :6]
    # PDMScorer keeps NC and DAC as multiplicative metrics.  DDC is the
    # first of the weighted metrics (its default weight is zero), followed
    # by TTC, EP, and Comfort.
    penalty = torch.prod(values[..., :2], dim=-1)
    behavior = (values[..., 2:] * weight_tensor[2:]).sum(dim=-1) / denominator
    return penalty * behavior


@dataclass(frozen=True)
class T4OracleResult:
    """Six original scorer heads and the original aggregate for a batch."""

    # [B, N, 6] = NC, DAC, DDC, TTC, EP, Comfort
    components: torch.Tensor
    # [B, N] returned by the scorer
    total: torch.Tensor
    # Dense trajectories without the current origin, [B, N, 40, 4]
    dense_proposals: torch.Tensor
    dense_reference: torch.Tensor


def interpolate_reference_trajectory(
    trajectories: torch.Tensor | np.ndarray,
    *,
    source_dt: float = MODEL_DT,
    target_dt: float = EVALUATOR_DT,
    num_model_poses: int = MODEL_NUM_POSES,
    num_evaluator_poses: int = EVALUATOR_NUM_POSES,
) -> torch.Tensor:
    """Return the public dense ``[... , 41, 4]`` trajectory representation.

    The formal scorer does not use this approximation helper: it uses the
    original NAVSIM ``transform_trajectory`` and ``get_trajectory_as_array``
    functions below.  Keeping this small representation helper is useful for
    audits and preserves the repository's existing API.
    """

    values = np.asarray(
        trajectories.detach().to(torch.float64).cpu().numpy()
        if torch.is_tensor(trajectories)
        else trajectories,
        dtype=np.float64,
    )
    if values.shape[-1] != 3 or values.shape[-2] != num_model_poses:
        raise ValueError(
            f"trajectory must have [...,{num_model_poses},3], got {values.shape}"
        )
    if source_dt <= 0.0 or target_dt <= 0.0:
        raise ValueError("trajectory sampling intervals must be positive")
    expected = int(round(num_model_poses * source_dt / target_dt))
    if expected != num_evaluator_poses:
        raise ValueError("model/evaluator sampling contract is inconsistent")

    source_times = np.arange(num_model_poses + 1, dtype=np.float64) * source_dt
    target_times = np.arange(num_evaluator_poses + 1, dtype=np.float64) * target_dt
    origin = np.zeros(values.shape[:-2] + (1, 3), dtype=np.float64)
    knot_values = np.concatenate((origin, values), axis=-2)
    flat = knot_values.reshape(-1, num_model_poses + 1, 3)
    dense = np.empty((flat.shape[0], num_evaluator_poses + 1, 4), dtype=np.float64)
    for index, sample in enumerate(flat):
        dense[index, :, 0] = np.interp(target_times, source_times, sample[:, 0])
        dense[index, :, 1] = np.interp(target_times, source_times, sample[:, 1])
        yaw = np.unwrap(sample[:, 2])
        yaw_dense = np.interp(target_times, source_times, yaw)
        dense[index, :, 2] = np.cos(yaw_dense)
        dense[index, :, 3] = np.sin(yaw_dense)
    dense = dense.reshape(values.shape[:-2] + (num_evaluator_poses + 1, 4))
    return torch.from_numpy(dense).to(
        device=trajectories.device if torch.is_tensor(trajectories) else "cpu",
        dtype=(
            trajectories.dtype
            if torch.is_tensor(trajectories) and trajectories.is_floating_point()
            else torch.float32
        ),
    )


def _np_batch(value: torch.Tensor | np.ndarray) -> np.ndarray:
    if torch.is_tensor(value):
        return value.detach().to(device="cpu", dtype=torch.float64).numpy()
    return np.asarray(value)


def _future_trajectory_to_metric(trajectory: torch.Tensor | np.ndarray) -> torch.Tensor:
    """Convert T4's 40 future ``[x,y,yaw]`` poses to ``[x,y,cos,sin]``."""

    values = trajectory if torch.is_tensor(trajectory) else torch.as_tensor(trajectory)
    if values.ndim != 3 or values.shape[-1] != 3 or values.shape[-2] != EVALUATOR_NUM_POSES:
        raise ValueError(
            "targets['oracle_future_trajectory'] must have shape [B,40,3], "
            f"got {tuple(values.shape)}"
        )
    yaw = values[..., 2]
    return torch.stack((values[..., 0], values[..., 1], yaw.cos(), yaw.sin()), dim=-1)


def _unpack_agent_targets(
    boxes: torch.Tensor,
    labels: torch.Tensor,
    mask: torch.Tensor,
    batch: int,
    frames: int,
) -> tuple[list[list[np.ndarray]], list[list[np.ndarray]]]:
    """Convert packed future T4 boxes into the original ragged observation."""

    if boxes.ndim != 4 or boxes.shape[:2] != (batch, frames) or boxes.shape[-1] != 9:
        raise ValueError(
            f"packed T4 future boxes must have shape [B,{frames},A,9], "
            f"got {tuple(boxes.shape)}"
        )
    if labels.shape != boxes.shape[:-1] or mask.shape != boxes.shape[:-1]:
        raise ValueError("packed T4 agent labels/mask do not match boxes")
    boxes_np = boxes.detach().cpu().numpy()
    labels_np = labels.detach().cpu().numpy()
    mask_np = mask.detach().cpu().numpy().astype(bool, copy=False)
    ragged_boxes: list[list[np.ndarray]] = []
    ragged_labels: list[list[np.ndarray]] = []
    for batch_index in range(batch):
        sample_boxes: list[np.ndarray] = []
        sample_labels: list[np.ndarray] = []
        for frame_index in range(frames):
            valid = mask_np[batch_index, frame_index]
            sample_boxes.append(np.ascontiguousarray(boxes_np[batch_index, frame_index, valid]))
            sample_labels.append(np.ascontiguousarray(labels_np[batch_index, frame_index, valid]))
        ragged_boxes.append(sample_boxes)
        ragged_labels.append(sample_labels)
    return ragged_boxes, ragged_labels


def _as_ragged_future_targets(
    targets: Mapping[str, Any], batch: int, frames: int
) -> tuple[list[np.ndarray], list[np.ndarray], list[list[np.ndarray]], list[list[np.ndarray]]]:
    """Read current + 5 s T4 GT without ever treating missing GT as empty."""

    current_boxes = targets.get("current_agent_boxes")
    current_labels = targets.get("current_agent_labels")
    if current_boxes is None or current_labels is None:
        raise KeyError(
            "T4 oracle labels require current_agent_boxes/current_agent_labels "
            "for the original 51-frame PDM observation"
        )

    future_boxes_value = targets.get("future_agent_boxes")
    future_labels_value = targets.get("future_agent_labels")
    if future_boxes_value is None or future_labels_value is None:
        raise KeyError("T4 oracle labels require future_agent_boxes/future_agent_labels")

    packed_mask = targets.get("future_agent_mask")
    if torch.is_tensor(future_boxes_value):
        if not torch.is_tensor(future_labels_value) or not torch.is_tensor(packed_mask):
            raise TypeError("packed T4 future boxes require packed labels and mask")
        future_boxes, future_labels = _unpack_agent_targets(
            future_boxes_value,
            future_labels_value,
            packed_mask,
            batch,
            frames,
        )
    else:
        if torch.is_tensor(future_labels_value) or torch.is_tensor(packed_mask):
            raise TypeError("ragged T4 future labels/mask cannot be tensors")
        if len(future_boxes_value) != batch or len(future_labels_value) != batch:
            raise ValueError("future agent box/label batch does not match proposals")
        future_boxes = [list(sample) for sample in future_boxes_value]
        future_labels = [list(sample) for sample in future_labels_value]

    if batch == 1 and isinstance(current_boxes, np.ndarray) and current_boxes.ndim == 2:
        current_boxes = [current_boxes]
    if batch == 1 and isinstance(current_labels, np.ndarray) and current_labels.ndim == 1:
        current_labels = [current_labels]
    if len(current_boxes) != batch or len(current_labels) != batch:
        raise ValueError("current agent box/label batch does not match proposals")

    current_boxes_out: list[np.ndarray] = []
    current_labels_out: list[np.ndarray] = []
    for index in range(batch):
        boxes = np.asarray(current_boxes[index], dtype=np.float64).reshape(-1, 9)
        labels = np.asarray(current_labels[index], dtype=np.int64).reshape(-1)
        if boxes.shape[0] != labels.shape[0]:
            raise ValueError(f"current T4 GT count mismatch at batch index {index}")
        if len(future_boxes[index]) != frames or len(future_labels[index]) != frames:
            raise ValueError(
                f"T4 future GT must contain exactly {frames} frames; "
                f"got {len(future_boxes[index])}/{len(future_labels[index])}"
            )
        for frame_boxes, frame_labels in zip(
            future_boxes[index], future_labels[index], strict=True
        ):
            if np.asarray(frame_boxes).reshape(-1, 9).shape[0] != np.asarray(frame_labels).reshape(-1).shape[0]:
                raise ValueError(f"future T4 GT count mismatch at batch index {index}")
        current_boxes_out.append(np.ascontiguousarray(boxes))
        current_labels_out.append(np.ascontiguousarray(labels))
    return current_boxes_out, current_labels_out, future_boxes, future_labels


def _proposal_states(
    proposals: np.ndarray,
    ego: Any,
    model_sampling: TrajectorySampling,
    proposal_sampling: TrajectorySampling,
) -> tuple[np.ndarray, np.ndarray]:
    """Use the exact original NAVSIM trajectory conversion for every proposal.

    ``transform_trajectory`` is untouched.  Only the sampling step is batched:
    ``get_trajectory_as_array`` rebuilds a full ``EgoState`` -- car footprint,
    oriented box, dynamic state -- for each of the 41 query times of each of
    the 64 proposals, and ``ego_state_to_state_array`` then reads back six of
    its numbers and discards the rest.  That is ~2600 constructions per window
    thrown away, and it was the single largest cost in the oracle after box
    association.

    What the discarded machinery actually computes is small: linear
    interpolation of the rear-axle x/y (plus velocity, acceleration and
    steering, which ``transform_trajectory`` fixes at zero) and angular
    interpolation of the heading.  ``from_split_state`` supplies the remaining
    three array columns from ``build_from_rear_axle``'s zero defaults.

    Every proposal shares one query-time axis, so the same ``interp1d`` and
    ``AngularInterpolator`` calls are made once over all proposals at once.
    Batching a column-independent interpolation cannot change a value, and
    ``tests/test_t4_oracle_evaluator.py`` pins the result against the original
    implementation.
    """

    proposals = np.asarray(proposals, dtype=np.float64)
    trajectories = [
        transform_trajectory(
            Trajectory(
                np.ascontiguousarray(proposal, dtype=np.float32),
                trajectory_sampling=model_sampling,
            ),
            ego,
        )
        for proposal in proposals
    ]

    # Query times: identical for every proposal, exactly as built by
    # get_trajectory_as_array.
    times_s = np.arange(
        0.0,
        proposal_sampling.time_horizon + proposal_sampling.interval_length,
        proposal_sampling.interval_length,
    )
    times_s += ego.time_point.time_s
    times_us = [int(time_s * 1e6) for time_s in times_s]
    reference = trajectories[0]
    times_us = np.clip(times_us, reference.start_time.time_us, reference.end_time.time_us)

    knot_times = np.array(
        [state.time_us for state in reference._trajectory], dtype=np.float64
    )
    linear = np.stack(
        [
            np.array([state.to_split_state().linear_states for state in trajectory._trajectory],
                     dtype=np.float64)
            for trajectory in trajectories
        ],
        axis=-1,
    )  # [knots, 8, proposals]
    angular = np.stack(
        [
            np.array([state.to_split_state().angular_states for state in trajectory._trajectory],
                     dtype=np.float64)
            for trajectory in trajectories
        ],
        axis=-1,
    )  # [knots, 1, proposals]

    knots, fields, count = linear.shape
    sampled_linear = interp1d(knot_times, linear.reshape(knots, fields * count), axis=0)(
        times_us
    ).reshape(-1, fields, count)
    sampled_angular = principal_value(
        interp1d(knot_times, np.unwrap(angular, axis=0).reshape(knots, count), axis=0)(times_us)
    )

    states = np.zeros((count, len(times_us), StateIndex.size()), dtype=np.float64)
    states[..., StateIndex.X] = sampled_linear[:, 1, :].T
    states[..., StateIndex.Y] = sampled_linear[:, 2, :].T
    states[..., StateIndex.HEADING] = sampled_angular.T
    states[..., StateIndex.VELOCITY_X] = sampled_linear[:, 3, :].T
    states[..., StateIndex.VELOCITY_Y] = sampled_linear[:, 4, :].T
    states[..., StateIndex.ACCELERATION_X] = sampled_linear[:, 5, :].T
    states[..., StateIndex.ACCELERATION_Y] = sampled_linear[:, 6, :].T
    states[..., StateIndex.STEERING_ANGLE] = sampled_linear[:, 7, :].T
    # STEERING_RATE, ANGULAR_VELOCITY and ANGULAR_ACCELERATION stay zero:
    # from_split_state never sets them, so build_from_rear_axle's defaults win.
    return states, states


def _simulate(
    states: np.ndarray,
    ego: Any,
    vehicle: Any,
    proposal_sampling: TrajectorySampling,
) -> np.ndarray:
    """Run the original PDM simulator with the T4 vehicle dimensions."""

    simulator = PDMSimulator(proposal_sampling)
    # The upstream simulator constructs these two pieces with Pacifica
    # defaults.  Replacing them is the necessary T4 vehicle adaptation; the
    # LQR/bicycle implementation itself remains untouched.
    simulator._motion_model._vehicle = vehicle
    simulator._tracker._wheel_base = vehicle.wheel_base
    return simulator.simulate_proposals(states, ego)


def _score_t4_oracle_sample(
    payload: tuple[
        np.ndarray,
        np.ndarray,
        np.ndarray,
        np.ndarray,
        np.ndarray,
        np.ndarray,
        np.ndarray,
        np.ndarray,
        list[np.ndarray],
        list[np.ndarray],
        float,
    ]
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Score one sample with the unchanged original PDM implementation.

    This is a module-level function so it can be run by a standard-library
    spawned process.  The tuple contains only CPU NumPy/ragged values; no
    CUDA tensor or model state crosses the process boundary.
    """

    (
        proposals,
        ego_shape,
        control,
        lanes,
        route,
        polygons,
        current_boxes,
        current_labels,
        future_boxes,
        future_labels,
        pdm_progress,
        roadblock_buffer_m,
    ) = payload

    model_sampling = TrajectorySampling(
        num_poses=MODEL_NUM_POSES, interval_length=MODEL_DT
    )
    proposal_sampling = TrajectorySampling(
        num_poses=PDM_PROPOSAL_NUM_POSES, interval_length=PDM_INTERVAL_S
    )
    trajectory_sampling = TrajectorySampling(
        num_poses=PDM_OBSERVATION_NUM_POSES, interval_length=PDM_INTERVAL_S
    )

    vehicle, ego = make_t4_vehicle_and_ego(
        ego_shape,
        control[:2],
        control[2:4],
        steering=float(control[4]),
        yaw_rate=float(control[5]),
    )
    states, _ = _proposal_states(proposals, ego, model_sampling, proposal_sampling)
    simulated_states = _simulate(states, ego, vehicle, proposal_sampling)
    dense_proposals = np.stack(
        (
            states[:, 1:, 0],
            states[:, 1:, 1],
            np.cos(states[:, 1:, 2]),
            np.sin(states[:, 1:, 2]),
        ),
        axis=-1,
    )

    centerline, _ = _route_path(route)
    drivable_map, route_lane_ids, _ = _build_drivable_map(
        {"lanes": lanes, "route": route, "polygons": polygons},
        roadblock_buffer_m=roadblock_buffer_m,
    )
    observation = make_t4_ground_truth_observation(
        [current_boxes, *future_boxes],
        [current_labels, *future_labels],
        trajectory_sampling=trajectory_sampling,
        proposal_sampling=proposal_sampling,
    )

    scorer = ReferencePDMScorer(
        proposal_sampling,
        vehicle_parameters=vehicle,
    )
    scores = scorer.score_proposals(
        simulated_states,
        observation,
        centerline,
        route_lane_ids,
        drivable_map,
        float(pdm_progress),
    )
    components = np.stack(
        (
            scorer._multi_metrics[MultiMetricIndex.NO_COLLISION],
            scorer._multi_metrics[MultiMetricIndex.DRIVABLE_AREA],
            scorer._weighted_metrics[WeightedMetricIndex.DRIVING_DIRECTION],
            scorer._weighted_metrics[WeightedMetricIndex.TTC],
            scorer._weighted_metrics[WeightedMetricIndex.PROGRESS],
            scorer._weighted_metrics[WeightedMetricIndex.COMFORTABLE],
        ),
        axis=-1,
    )
    if not np.isfinite(components).all() or not np.isfinite(scores).all():
        raise ValueError("original T4 PDM scorer produced non-finite values")
    # ``PDMScorer.score_proposals`` catches a failing ``_calculate_ttc`` and
    # marks the *whole call* with the NAVSIM "not evaluated" sentinel.  That
    # scope is per call, so a chunked window must report it and be re-scored
    # whole rather than have the sentinel applied to one chunk only.
    ttc_fallback = bool((components[..., 3] == 2.0).any())
    return scores, components, dense_proposals, ttc_fallback


@dataclass
class PendingT4Oracle:
    """An oracle call that has been dispatched but not yet collected.

    The training step's critical path is GPU forward -> **wait for the CPU
    oracle** -> loss/backward, and the oracle wait is ~50% of the step while
    the GPUs sit idle.  Splitting ``score`` into a submit half (validation and
    payload preparation, then non-blocking ``executor.submit``) and a wait
    half (gather, TTC repair, tensor assembly) lets a caller overlap the
    oracle of one micro-batch with the GPU work of the next.  ``score`` itself
    is unchanged: it is submit immediately followed by wait, and produces
    bit-identical results.
    """

    proposals_ref: torch.Tensor
    batch: int
    proposal_count: int
    tasks: list
    bounds_count: int
    futures: list | None
    payloads: list | None
    payload_fn: Any
    executor: Any
    reference_np: np.ndarray
    device: Any
    # (scores, components, dense) already computed by the GPU oracle: the
    # submit half scored eagerly on-device and the wait half only assembles.
    precomputed: Any = None


@dataclass(frozen=True)
class T4OracleEvaluator:
    """Evaluate proposals using the original six PDM scorer components."""

    config: Any

    def __post_init__(self) -> None:
        model_num_poses = int(_cfg_get(self.config, "num_poses", MODEL_NUM_POSES))
        model_dt = float(_cfg_get(self.config, "t4_trajectory_dt_s", MODEL_DT))
        if model_num_poses != MODEL_NUM_POSES or model_dt != MODEL_DT:
            raise ValueError(
                "T4 scorer must preserve the trajectory contract: "
                f"{MODEL_NUM_POSES} poses at {MODEL_DT}s; got {model_num_poses} at {model_dt}s"
            )
        oracle_num_poses = int(
            _cfg_get(self.config, "t4_oracle_num_poses", EVALUATOR_NUM_POSES)
        )
        oracle_dt = float(_cfg_get(self.config, "t4_oracle_dt_s", EVALUATOR_DT))
        if oracle_num_poses != EVALUATOR_NUM_POSES or oracle_dt != EVALUATOR_DT:
            raise ValueError("T4 PDM scorer must use the original 40-point/10 Hz evaluator")
        configured_observation = int(
            _cfg_get(self.config, "t4_pdm_observation_frames", PDM_OBSERVATION_NUM_POSES)
        )
        if configured_observation != PDM_OBSERVATION_NUM_POSES:
            raise ValueError(
                "T4 PDM observation must retain the original 5 s TTC context "
                f"({PDM_OBSERVATION_NUM_POSES} future frames)"
            )

    def score(
        self,
        proposals: torch.Tensor,
        targets: Mapping[str, Any],
        features: Mapping[str, Any],
    ) -> T4OracleResult:
        """Return detached original PDM labels for every learned proposal."""

        return self.score_wait(self.score_submit(proposals, targets, features))

    def score_submit(
        self,
        proposals: torch.Tensor,
        targets: Mapping[str, Any],
        features: Mapping[str, Any],
        pool_windows: int | None = None,
    ) -> PendingT4Oracle:
        """Validate, build payloads, and dispatch without blocking.

        ``pool_windows`` sizes the worker pool when several submissions are
        meant to run concurrently.  Sizing by this call's own task count --
        the historical behaviour, kept as the default -- resized the shared
        pool down to the micro-batch (respawning it in the process) and made
        concurrent micro-batches queue behind each other, which is exactly
        what the first pipeline benchmark measured: 956 -> 1166 ms.  A
        pipelined caller passes the full per-rank batch here so the pool
        keeps one worker per window in flight.
        """

        if proposals.ndim != 4 or proposals.shape[-1] != 3 or proposals.shape[-2] != MODEL_NUM_POSES:
            raise ValueError(
                "T4 proposals must have shape [B,N,8,3], "
                f"got {tuple(proposals.shape)}"
            )
        batch, proposal_count, _, _ = proposals.shape

        reference = targets.get("oracle_future_trajectory")
        if reference is None:
            raise KeyError("T4 oracle labels require oracle_future_trajectory")
        reference_metric = _future_trajectory_to_metric(reference)
        if reference_metric.shape[0] != batch:
            raise ValueError("oracle future trajectory batch does not match proposals")

        available = targets.get("agent_gt_available")
        if available is not None:
            if torch.is_tensor(available):
                available = available.detach().cpu().tolist()
            if len(available) != batch or not all(bool(value) for value in available):
                raise ValueError(
                    "T4 oracle scoring requires complete future agent GT for every sample"
                )

        oracle_device = str(
            _cfg_get(self.config, "t4_oracle_device", "cpu") or "cpu"
        ).lower()
        scene_arrays = targets.get("oracle_scene")
        if scene_arrays is not None and len(scene_arrays) != batch:
            raise ValueError("targets['oracle_scene'] length does not match the batch")
        if oracle_device == "cpu":
            # The CPU reference path owns its raw map/track conversion and
            # must never consume a loader-side GPU payload accidentally.
            scene_arrays = None

        # GPU reference labels are generated online when no denominator was
        # supplied.  CPU mode remains an explicit reference path and refuses
        # to invent a denominator or call the GPU implementation implicitly.
        pdm_progress = targets.get("pdm_progress")
        if oracle_device == "cpu" and pdm_progress is None:
            raise KeyError(
                "T4 oracle labels in CPU mode require pdm_progress; online "
                "PDM-Closed generation is GPU-only"
            )

        need_raw_targets = (
            oracle_device == "cpu"
            or scene_arrays is None
            or pdm_progress is None
        )
        if need_raw_targets:
            current_boxes, current_labels, future_boxes, future_labels = (
                _as_ragged_future_targets(targets, batch, PDM_OBSERVATION_NUM_POSES)
            )
        else:
            current_boxes = current_labels = None
            future_boxes = future_labels = None
        ego_shapes = _np_batch(features.get("ego_shape"))
        if ego_shapes.shape != (batch, 3):
            raise ValueError(f"T4 ego_shape must have shape [B,3], got {ego_shapes.shape}")
        control_states = features.get("control_state")
        if control_states is None:
            raise KeyError("T4 oracle evaluator requires features['control_state']")
        control_states_np = _np_batch(control_states)
        if control_states_np.shape != (batch, 6):
            raise ValueError(
                "T4 control_state must have [B,6] = [velocity(2),acceleration(2),steering,yaw_rate], "
                f"got {control_states_np.shape}"
            )

        if scene_arrays is None:
            map_fields = ("lanes", "route_lanes", "polygons")
            missing_map = [name for name in map_fields if name not in features]
            if missing_map:
                raise KeyError(
                    f"T4 oracle evaluator requires HD-map fields {missing_map}"
                )
            lanes = _np_batch(features["lanes"])
            routes = _np_batch(features["route_lanes"])
            polygons = _np_batch(features["polygons"])
            if (
                lanes.shape[0] != batch
                or routes.shape[0] != batch
                or polygons.shape[0] != batch
            ):
                raise ValueError("T4 HD-map fields have inconsistent batch dimensions")
        else:
            lanes = routes = polygons = None

        target = None
        if oracle_device != "cpu":
            if oracle_device in ("gpu", "cuda"):
                target = torch.device("cuda", torch.cuda.current_device())
            else:
                target = torch.device(oracle_device)
            if target.type != "cuda" or not torch.cuda.is_available():
                raise ValueError(
                    "online T4 oracle scoring requires CUDA; CPU mode must be requested "
                    "explicitly and never appears as an automatic fallback"
                )

        # When the loader did not pre-pack the scene, do the one-time variable
        # length map/track packing here.  This is input preparation only; all
        # PDM candidate generation, simulation and metric kernels stay on GPU.
        if oracle_device != "cpu" and scene_arrays is None:
            from t4_e2e_devkit.evaluation.gpu.scene import extract_window_scene_arrays

            scene_arrays = [
                extract_window_scene_arrays(
                    lanes[index],
                    routes[index],
                    polygons[index],
                    [current_boxes[index], *future_boxes[index]],
                    [current_labels[index], *future_labels[index]],
                    roadblock_buffer_m=float(
                        _cfg_get(self.config, "t4_drivable_area_buffer_m", PDM_ROADBLOCK_BUFFER_M)
                    ),
                )
                for index in range(batch)
            ]

        progress_tensor = None
        progress_values = None
        if pdm_progress is not None:
            if oracle_device != "cpu" and torch.is_tensor(pdm_progress):
                progress_tensor = pdm_progress.reshape(-1).to(device=target)
            else:
                progress_values = _np_batch(pdm_progress).reshape(-1)
                if oracle_device != "cpu":
                    progress_tensor = torch.as_tensor(
                        progress_values, device=target, dtype=torch.float32
                    )
            if progress_tensor is not None:
                if progress_tensor.shape != (batch,):
                    raise ValueError("targets['pdm_progress'] must have shape [B]")
                if not bool(torch.isfinite(progress_tensor).all().item()) or bool(
                    (progress_tensor < 0.0).any().item()
                ):
                    raise ValueError("targets['pdm_progress'] must be finite and non-negative [B]")
            elif (
                progress_values.shape != (batch,)
                or not np.isfinite(progress_values).all()
                or (progress_values < 0.0).any()
            ):
                raise ValueError("targets['pdm_progress'] must be finite and non-negative [B]")

        if oracle_device != "cpu" and pdm_progress is None:
            if scene_arrays is None:
                raise RuntimeError(
                    "online GPU PDM-Closed generation needs packed scene arrays or "
                    "complete raw T4 map and agent targets"
                )
            route_speed = features.get("route_lanes_speed_limit")
            route_has_speed = features.get("route_lanes_has_speed_limit")
            if route_speed is None or route_has_speed is None:
                raise KeyError(
                    "online GPU PDM-Closed generation requires route speed-limit fields"
                )
            route_speed_np = _np_batch(route_speed)
            route_has_speed_np = _np_batch(route_has_speed).astype(bool, copy=False)
            from t4_e2e_devkit.evaluation.gpu.reference import (
                OnlinePDMReferenceInput,
                compute_online_pdm_references_from_arrays,
            )

            online_inputs = [
                OnlinePDMReferenceInput(
                    scene_arrays=scene_arrays[index],
                    current_boxes=current_boxes[index],
                    current_labels=current_labels[index],
                    ego_shape=ego_shapes[index],
                    control=control_states_np[index],
                    route_speed=route_speed_np[index],
                    route_has_speed=route_has_speed_np[index],
                    token=f"batch[{index}]",
                )
                for index in range(batch)
            ]
            online = compute_online_pdm_references_from_arrays(
                online_inputs,
                device=target,
                dtype=torch.float64,
                roadblock_buffer_m=float(
                    _cfg_get(self.config, "t4_drivable_area_buffer_m", PDM_ROADBLOCK_BUFFER_M)
                ),
            )
            progress_tensor = online.pdm_progress

        # The oracle labels and the cached pdm_progress denominator must be
        # produced by the same drivable-area geometry, so this reads the value
        # that also feeds T4PDMReferenceConfig.signature.
        roadblock_buffer_m = float(
            _cfg_get(self.config, "t4_drivable_area_buffer_m", PDM_ROADBLOCK_BUFFER_M)
        )

        light_gpu = oracle_device != "cpu" and scene_arrays is not None
        if light_gpu:
            # Loader-side scene arrays already contain the variable-length map
            # and recorded-track geometry.  Do not rebuild it or route through
            # the CPU PDM scorer.
            lanes = routes = polygons = None

        proposals_np = proposals.detach().to(device="cpu", dtype=torch.float64).numpy()

        # Build the same per-sample inputs used by the original serial loop.
        # Only the scheduling boundary changes; each worker still executes the
        # exact original trajectory conversion, simulator, and PDM scorer.
        # With loader-side scene prep the heavy map/box fields are unused and
        # left out; only the fallback GPU path and the CPU pool pack them.
        def _payload(batch_index: int, proposal_slice: slice) -> tuple:
            progress_value = (
                progress_tensor[batch_index]
                if progress_tensor is not None
                else float(progress_values[batch_index])
            )
            return (
                np.ascontiguousarray(proposals_np[batch_index][proposal_slice]),
                np.ascontiguousarray(ego_shapes[batch_index]),
                np.ascontiguousarray(control_states_np[batch_index]),
                None if light_gpu else np.ascontiguousarray(lanes[batch_index]),
                None if light_gpu else np.ascontiguousarray(routes[batch_index]),
                None if light_gpu else np.ascontiguousarray(polygons[batch_index]),
                None if light_gpu else np.ascontiguousarray(current_boxes[batch_index]),
                None if light_gpu else np.ascontiguousarray(current_labels[batch_index]),
                None
                if light_gpu
                else [np.ascontiguousarray(value) for value in future_boxes[batch_index]],
                None
                if light_gpu
                else [np.ascontiguousarray(value) for value in future_labels[batch_index]],
                progress_value,
                roadblock_buffer_m,
            )

        if oracle_device != "cpu":
            # GPU oracle: score every window eagerly on-device (fp32 by
            # default; validated against the CPU oracle -- 100% agreement on
            # the five discrete components, EP within ~3e-5).  Whole-window
            # payloads by construction, so the TTC sentinel repair and the
            # worker pool are both moot.
            from t4_e2e_devkit.evaluation.gpu.oracle import score_payloads_gpu

            if oracle_device in ("gpu", "cuda"):
                target = torch.device("cuda", torch.cuda.current_device())
            else:
                target = torch.device(oracle_device)
            gpu_dtype = (
                torch.float64
                if str(
                    _cfg_get(self.config, "t4_oracle_gpu_dtype", "float32")
                ).lower()
                == "float64"
                else torch.float32
            )
            whole = [
                _payload(index, slice(0, proposal_count)) for index in range(batch)
            ]
            # The training step runs under AMP autocast; oracle labels must
            # not: fp16 matmuls degrade the validated fp32 label precision
            # and the batched LU solve has no Half kernel at all.
            with torch.no_grad(), torch.autocast(
                device_type=target.type, enabled=False
            ):
                precomputed = score_payloads_gpu(
                    whole, target, gpu_dtype, scene_arrays=scene_arrays
                )
            return PendingT4Oracle(
                proposals_ref=proposals,
                batch=batch,
                proposal_count=proposal_count,
                tasks=[(index, slice(0, proposal_count)) for index in range(batch)],
                bounds_count=1,
                futures=None,
                payloads=None,
                payload_fn=_payload,
                executor=None,
                reference_np=_np_batch(reference).astype(np.float64, copy=False),
                device=proposals.device,
                precomputed=precomputed,
            )

        workers = _t4_oracle_worker_count(batch)
        chunks = _t4_oracle_chunk_count(batch, proposal_count, workers)
        # Contiguous slices keep proposal order, so results reassemble by
        # construction rather than by sorting.
        bounds = [
            slice(start, min(start + -(-proposal_count // chunks), proposal_count))
            for start in range(0, proposal_count, -(-proposal_count // chunks))
        ]
        tasks = [
            (batch_index, proposal_slice)
            for batch_index in range(batch)
            for proposal_slice in bounds
        ]
        # One worker per task in flight: a pipelined caller has
        # pool_windows windows outstanding across its micro-batches, each
        # split into `chunks` tasks.
        pool_span = len(tasks) if pool_windows is None else max(
            int(pool_windows) * chunks, len(tasks)
        )
        workers = _t4_oracle_worker_count(pool_span)
        payloads = [_payload(batch_index, sl) for batch_index, sl in tasks]
        executor = _get_t4_oracle_executor(workers)
        futures = None
        if executor is not None:
            # submit() rather than map(): dispatch returns immediately and the
            # caller decides when to block, which is what enables overlapping
            # this CPU work with the next micro-batch's GPU forward.
            futures = [executor.submit(_score_t4_oracle_sample, p) for p in payloads]
        return PendingT4Oracle(
            proposals_ref=proposals,
            batch=batch,
            proposal_count=proposal_count,
            tasks=tasks,
            bounds_count=len(bounds),
            futures=futures,
            payloads=None if futures is not None else payloads,
            payload_fn=_payload,
            executor=executor,
            reference_np=_np_batch(reference).astype(np.float64, copy=False),
            device=proposals.device,
        )

    def score_wait(self, pending: PendingT4Oracle) -> T4OracleResult:
        """Collect a dispatched oracle call; identical output to ``score``."""

        batch, proposal_count = pending.batch, pending.proposal_count
        if pending.precomputed is not None:
            all_scores, all_components, dense_proposals = pending.precomputed
            reference_np = pending.reference_np
            dense_reference = np.stack(
                (
                    reference_np[..., 0],
                    reference_np[..., 1],
                    np.cos(reference_np[..., 2]),
                    np.sin(reference_np[..., 2]),
                ),
                axis=-1,
            )
            return T4OracleResult(
                components=torch.as_tensor(
                    all_components, device=pending.device, dtype=torch.float32
                ),
                total=torch.as_tensor(
                    all_scores, device=pending.device, dtype=torch.float32
                ),
                dense_proposals=torch.as_tensor(
                    dense_proposals, device="cpu", dtype=torch.float64
                ),
                dense_reference=torch.as_tensor(
                    dense_reference, device="cpu", dtype=torch.float64
                ),
            )
        all_components = np.empty((batch, proposal_count, 6), dtype=np.float64)
        all_scores = np.empty((batch, proposal_count), dtype=np.float64)
        dense_proposals = np.empty(
            (batch, proposal_count, EVALUATOR_NUM_POSES, 4), dtype=np.float64
        )
        if pending.futures is not None:
            results = [future.result() for future in pending.futures]
        else:
            results = [_score_t4_oracle_sample(p) for p in pending.payloads]
        tasks, _payload, executor = pending.tasks, pending.payload_fn, pending.executor

        needs_whole_window: set[int] = set()
        for (batch_index, proposal_slice), (scores, components, dense, ttc_fallback) in zip(
            tasks, results, strict=True
        ):
            all_scores[batch_index, proposal_slice] = scores
            all_components[batch_index, proposal_slice] = components
            dense_proposals[batch_index, proposal_slice] = dense
            if ttc_fallback and pending.bounds_count > 1:
                needs_whole_window.add(batch_index)

        # The TTC sentinel is defined over a whole scorer call.  Re-score those
        # windows unsplit so the chunked and unchunked results are identical.
        if needs_whole_window:
            repair = sorted(needs_whole_window)
            repair_payloads = [_payload(index, slice(0, proposal_count)) for index in repair]
            if executor is None:
                repaired = [_score_t4_oracle_sample(payload) for payload in repair_payloads]
            else:
                repaired = list(executor.map(_score_t4_oracle_sample, repair_payloads))
            for batch_index, (scores, components, dense, _) in zip(
                repair, repaired, strict=True
            ):
                all_scores[batch_index] = scores
                all_components[batch_index] = components
                dense_proposals[batch_index] = dense

        reference_np = pending.reference_np
        dense_reference = np.stack(
            (
                reference_np[..., 0],
                reference_np[..., 1],
                np.cos(reference_np[..., 2]),
                np.sin(reference_np[..., 2]),
            ),
            axis=-1,
        )
        device = pending.device
        return T4OracleResult(
            components=torch.as_tensor(all_components, device=device, dtype=torch.float32),
            total=torch.as_tensor(all_scores, device=device, dtype=torch.float32),
            dense_proposals=torch.as_tensor(dense_proposals, device="cpu", dtype=torch.float64),
            dense_reference=torch.as_tensor(dense_reference, device="cpu", dtype=torch.float64),
        )
